<?php
namespace App\Domain\WorkProcesses; use App\Domain\PublicChrome\PublicAssetPath; use App\Models\WorkProcess; use Illuminate\Support\Facades\Cache; use Throwable; final class WorkProcessIndexViewData { public function get(int $page):array{try{return Cache::remember('public.work-processes.index.v1.'.WorkProcessCache::indexVersion().'.'.now()->format('YmdHi').'.'.$page,now()->addMinutes(10),fn()=>$this->load($page));}catch(Throwable){return $this->load($page);}} private function load(int $page):array{$p=WorkProcess::publiclyVisible()->orderByDesc('is_featured')->orderBy('display_order')->paginate(12,['*'],'page',$page);return ['items'=>$p->getCollection()->map(fn($item)=>['title'=>$item->title,'description'=>$item->short_description,'featured'=>(bool)$item->is_featured,'image'=>PublicAssetPath::isSafe($item->featured_image_path)?$item->featured_image_path:null,'image_alt'=>$item->featured_image_alt,'url'=>route('work-processes.show',$item->slug)])->all(),'pagination'=>['current'=>$p->currentPage(),'last'=>$p->lastPage(),'previous'=>$p->previousPageUrl(),'next'=>$p->nextPageUrl(),'total'=>$p->total()]];} }
